String resolveCodeTheme(String theme, bool dark) =>
    legacyCodeThemes[theme]?[dark ? 1 : 0] ??
    (codeThemeColors.containsKey(theme)
        ? theme
        : dark
        ? 'one-dark-pro'
        : 'one-light');
